tafsir_text:
{  وَاذْكُرُواْ نِعْمَةَ اللّهِ عَلَيْكُمْ وَمِيثَاقَهُ الَّذِي وَاثَقَكُم بِهِ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا وَاتَّقُواْ اللّهَ إِنَّ اللّهَ عَلِيمٌ بِذَاتِ الصُّدُورِ }

المعنى :

{  واذكروا نعمة الله عليكم وميثاقه الذي واثقكم به } .  كل من دخل في دين أو حزب فقد قطع عهدا على نفسه أن يستجيب لمبادئه وتعاليمه ،  ويعمل بها عن رضى وطيب نفس .  .  وهذا هو الميثاق الذي واثقنا الله به نحن المسلمين حين ارتضينا الإسلام دينا ،  ومن قام بهذا الميثاق وأداه كما أمر الله فقد وفى مع الله ،  ومن عصى فقد خان الله ،  ومن أظهر معاني الوفاء لله سبحانه الإخلاص لعباده ،  والصدق في معاملتهم ،  ولا أعرف علامة على الصدق في الدين حقا وواقعا غير الوفاء .  .  وأنصح كل إنسان أن لا يأتمن أحدا لعلمه أو عبادته أو لمنصبه وشهرته بل يأتمنه ويثق به بعد اليقين بصدقه ووفائه .

{  وَالَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِآيَاتِنَا أُوْلَئِكَ أَصْحَابُ الْجَحِيمِ }

المعنى :

{  والذين كفروا وكذبوا بآياتنا أولئك أصحاب الجحيم } .  بعد أن وعد المؤمنين العاملين بالنعيم توعد الكافرين بالجحيم على طريقته تعالى من تعقيب الترغيب بالترهيب .  .  وفي هذه الآية دلالة واضحة على أن من كفر بالله فهو من أصحاب الجحيم ،  وان لم يدعه إلى الإيمان نبي أو وصي نبي .  ذلك أن آياته تعالى التي تقوم بها الحجة على وجوده لا تختص بما أنزله على رسله ،  فلقد أقام الدليل الكافي على وحدانيته وعظمته من الأنفس والسموات والأرض ،  فمن يكفر بها تلزمه الحجة :  {  أو لم يتفكروا في أنفسهم ما خلق الله السموات والأرض وما بينهما إلا بالحق- 8 الروم } .

{  قَالُوا يَا مُوسَى إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىَ يَخْرُجُواْ مِنْهَا فَإِن يَخْرُجُواْ مِنْهَا فَإِنَّا دَاخِلُونَ }

اللغة :

الجبار للمبالغة .  ويستعمل في إصلاح الأمور ،  يقال :  جبر كسره إذا أصلحه ، وجبر الفقير إذا أنعشه ،  وأيضا يستعمل في ذم الإنسان المتكبر المتعاظم وهذا هو المراد هنا .  وإذا وصف ذو الجلال به فالمراد به العالي الذي لا ينال ،  حتى العقول تعجز عن إدراك كنهه وحقيقته ،  ومن ذلك قول العرب :  نخلة جبارة ،  إذا طالت وعلت وقصرت الأيدي عن تناولها .

المعنى :

ولكن قوم موسى قالوا له جبنا وضعفا :  {  يا موسى إن فيها قوما جبارين وإنا لن ندخلها حتى يخرجوا منها فإن يخرجوا منها فإنا داخلون } فهم يريدون نصرا رخيصا ومريحا لا يكلفهم قتيلا ولا جريحا ،  تماما كإغراق عدوهم فرعون .  .  ولكن رجلين صالحين منهم قاما فيهم مرشدين يحثانهم على السمع والطاعة ولرسوله ، وإليهما أشار سبحانه بقوله : {  قَالَ رَجُلاَنِ مِنَ الَّذِينَ يَخَافُونَ أَنْعَمَ اللّهُ عَلَيْهِمَا ادْخُلُواْ عَلَيْهِمُ الْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَالِبُونَ وَعَلَى اللّهِ فَتَوَكَّلُواْ إِن كُنتُم مُّؤْمِنِينَ }

{  قَالَ رَبِّ إِنِّي لا أَمْلِكُ إِلاَّ نَفْسِي وَأَخِي فَافْرُقْ بَيْنَنَا وَبَيْنَ الْقَوْمِ الْفَاسِقِينَ }

المعنى :

{  قال رب إني لا أملك إلا نفسي وأخي } هذا التوجه من موسى إلى ربه يشعر بالشكوى من غربته بين قومه ،  بعد الجهد الجهيد والعناء الطويل من أجلهم .  .  {  إني لا أملك إلا نفسي وأخي } ولا ملك ولا أمر لمن لا يطاع :  {  فافرق بيننا وبين القوم الفاسقين } .  لم يجد موسى بدا من الطلب إليه تعالى أن يفصل ويباعد بينه وبين قومه ،  بعد نكولهم عن عهد الله وميثاقه .

{  يُرِيدُونَ أَن يَخْرُجُواْ مِنَ النَّارِ وَمَا هُم بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُّقِيمٌ }

المعنى :

{  يريدون أن يخرجوا من النار وما هم بخارجين منها ولهم عذاب مقيم } وهذا نص قاطع على أن من جحد الخالق أو عبد سواه ،  فهو مخلد في النار {  وما هم بخارجين منها } . وفي الآية 20 من سورة السجدة :  {  كلما أرادوا أن يخرجوا منها أعيدوا فيها وقيل لهم ذوقوا عذاب النار الذي كنتم به تكذبون } .  وهناك جرائم لا تقل إثما وعذابا عن الكفر بالله ،  كسلب الشعوب أقواتها ومقومات حياتها ،  وقتل النفس ،  لأنها أبت إلا أن تعيش حرة كريمة .

{  وَمَن يَتَوَلَّ اللّهَ وَرَسُولَهُ وَالَّذِينَ آمَنُواْ فَإِنَّ حِزْبَ اللّهِ هُمُ الْغَالِبُونَ }

المعنى :

{  ومن يتول الله ورسوله والذين آمنوا فإن حزب الله هم الغالبون } .  هذه الآية نص صريح لا يقبل التأويل بحال ، على أن المعنى المراد من ولاية الله والرسول والمؤمنين واحد لا اختلاف فيه ،  وأن من حافظ على هذه الآية ولم يفرق بين الله ورسوله ،  ومن جمع بين الزكاة والركوع فهو من حزب الله الغالب بمنطق الحق وحجته .

{  وَلَوْ أَنَّ أَهْلَ الْكِتَابِ آمَنُواْ وَاتَّقَوْاْ لَكَفَّرْنَا عَنْهُمْ سَيِّئَاتِهِمْ وَلأدْخَلْنَاهُمْ جَنَّاتِ النَّعِيمِ }

المعنى :

{  ولو أن أهل الكتاب آمنوا واتقوا لكفرنا عنهم سيئاتهم ولأدخلناهم جنات النعيم } .  هذه دعوة من الله سبحانه لليهود والنصارى أن يتوبوا ويدخلوا في الإسلام ،  وإن استجابوا لدعوته صفح عن جميع ذنوبهم ،  وإن عظمت ،  لأن الإسلام  يجب ما قبله ،  كما جاء في الحديث ،  وإن اتقوا بعد إسلامهم أدخلهم جنات تجري من تحتها الأنهار .

{  أَفَلاَ يَتُوبُونَ إِلَى اللّهِ وَيَسْتَغْفِرُونَهُ وَاللّهُ غَفُورٌ رَّحِيمٌ }

المعنى :

{  أفلا يتوبون إلى الله ويستغفرونه والله غفور رحيم } ما أوضح هذا الكلام ورغم هذا الوضوح أبى بعض المفسرين إلا أن يفسره ويقول :   " هنا فعل محذوف ،  والتقدير أفلا يسمعون ما قلنا فيتوبون "  وهكذا يأتي الشيء جامدا باردا إذا كان في غير محله .

{  وَأَطِيعُواْ اللّهَ وَأَطِيعُواْ الرَّسُولَ وَاحْذَرُواْ فَإِن تَوَلَّيْتُمْ فَاعْلَمُواْ أَنَّمَا عَلَى رَسُولِنَا الْبَلاَغُ الْمُبِينُ }

المعنى :

{  وأطيعوا الله وأطيعوا الرسول } في ترك الخمر والميسر وغيرهما من المحرمات {  واحذروا } ما يصيبكم من عذاب الله إذا خالفتم أمره وأمر رسوله .  قال الإمام علي ( ع ) :  أنصح الناس لنفسه أطوعهم لربه ،  وأغشهم لنفسه أعصاهم لربه .  {  فإن توليتم فاعلموا أنما على الرسول البلاغ المبين } وقد أداه كاملا وأقام الحجة على الناس ،  وخرج عن عهدة التبليغ ،  ومن خالف فهو وحده المسؤول .

{  اعْلَمُواْ أَنَّ اللّهَ شَدِيدُ الْعِقَابِ وَأَنَّ اللّهَ غَفُورٌ رَّحِيمٌ }

المعنى :

{  اعلموا أن الله شديد العقاب وأن الله غفور رحيم } .  قرن سبحانه العذاب بالرحمة والمغفرة ليكون العبد خائفا من نقمته راجيا لرحمته .  لأنه إذا خاف ابتعد عن المعصية ،  وإذا رجا اجتهد في الطاعة .  قال الرازي- ونعم ما قال- :  " ذكر سبحانه أنه شديد العقاب ثم عقب بوصف الرحمة والمغفرة ،  وهذا تنبيه على دقيقة ،  وهي أن ابتداء الخلق والإيجاد كان لأجل الرحمة ،  والظاهر أن الختم لا يكون إلا على الرحمة "  .  .  هذا هو الصحيح .

{  مَّا عَلَى الرَّسُولِ إِلاَّ الْبَلاَغُ وَاللّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ }

المعنى :

{  ما على الرسول إلا البلاغ } ولا يطلب منه أكثر من ذلك حيث لا عذر بعد البلاغ لمن أهمل وفرط ،  أما الحساب والعقاب فعلى الله وحده :  {  فإنما عليك البلاغ وعلينا الحساب- 41 الرعد } .  {  والله يعلم ما تبدون } من الأقوال والأفعال {  وما تكتمون } هذا تهديد لمن يسكت عن الحق ،  وبالأولى لمن يتاجر به مستترا باسم الدين والوطنية .

{  قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُواْ بِهَا كَافِرِينَ }

المعنى :

{  قد سألها قوم من قبلكم ثم أصبحوا بها كافرين } بعد أن نهاهم سبحانه عن السؤال عن أشياء هم في غنى عنها ،  ضرب لهم مثلا بمن كان قبلهم ،  سألوا وشددوا على أنفسهم بالسؤال ،  ولما بين الله لهم كرهوا وتمردوا فاستحقوا العذاب ،  ولو تركوا السؤال لكان خيرا لهم .  .  وقد أطال المفسرون الكلام في بيان المراد من القوم الذين سألوا ثم أصبحوا كافرين بسبب السؤال ،  ولكن الآية أبهمت ولم تبين .  .  ومع ذلك لنا أن نقول :  عن القوم الذين سألوا وكفروا هم بنو إسرائيل لقوله تعالى حكاية عنهم :  {  فقد سألوا موسى أكبر من ذلك فقالوا أرنا الله جهرة- 152 النساء } .

{  لِلّهِ مُلْكُ السَّمَاوَاتِ وَالأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِير }

المعنى :

{  لله ملك السموات والأرض وما فيهن وهو على كل شيء قدير } ومن كانت له هذه المقدرة وهذا الملك أعطى من يرضى عنه بغير حساب .
